import React from 'react';
import './About.css';

const About = () => {
  return (
    <section id="about" className="section">
      <h2 className="section-title fade-up">About Me</h2>
      <div className="about-content fade-up">
        <p>I am a Software Developer currently building innovative digital experiences at <strong>Sookshum Labs</strong> in Mohali, Punjab. With over two years of dedicated hands-on experience, my core expertise is rooted in crafting robust, high-performance web applications.</p>
        <p>While I specialize deeply in <strong>Magento 2</strong> architecture, I also bring a strong, versatile working knowledge of <strong>Shopify</strong> and <strong>WordPress</strong>. My philosophy is simple: write clean, maintainable code that translates into beautifully customized, lightning-fast platforms tailored to modern business needs.</p>
      </div>
    </section>
  );
};

export default About;
